questionvariables.text:
/* Curated (triangle, line) variants.  line = [kind, off]:
   kind 1 = horizontal y = off ; 2 = vertical x = off ; 3 = y = x + off ; 4 = y = -x + off.
   Each triangle sits fully on one side of its line, so the image is clear of the original,
   and all coordinates stay on the board. */
variants : [
  [[[-4,-3],[-4,-1],[1,-4]],1,0],
  [[[-2,-3],[2,-4],[3,-2]],1,0],
  [[[-4,-4],[-4,1],[-2,-4]],2,0],
  [[[2,0],[3,-3],[4,2]],2,0],
  [[[-2,0],[0,3],[2,4]],3,0],
  [[[-2,-3],[2,-4],[3,-2]],3,0],
  [[[-4,-3],[-4,-1],[1,-4]],4,0],
  [[[-4,-4],[-4,1],[-2,-4]],4,0],
  [[[-2,0],[2,1],[3,0]],1,3],
  [[[-3,2],[0,0],[0,2]],1,3],
  [[[-1,-1],[0,2],[2,-1]],1,-2],
  [[[-2,0],[2,1],[3,0]],1,-2],
  [[[-4,-4],[-4,1],[-2,-4]],2,1],
  [[[-4,-4],[-1,1],[0,-2]],2,1],
  [[[-1,-1],[0,2],[2,-1]],2,-2],
  [[[-1,-1],[0,2],[1,-2]],2,-2],
  [[[-2,0],[0,3],[2,4]],3,1],
  [[[-2,-3],[2,-4],[3,-2]],3,1],
  [[[-2,0],[0,3],[2,4]],3,-1],
  [[[-2,4],[2,2],[3,4]],3,-1],
  [[[-3,0],[1,-3],[1,-1]],4,1],
  [[[-4,-3],[-4,-1],[1,-4]],4,1],
  [[[-4,-3],[-4,-1],[1,-4]],4,-2],
  [[[-4,-4],[-4,1],[-2,-4]],4,-2]
];

V : rand(variants);
tri : V[1];
kind : V[2];
off : V[3];

/* general line reflection */
reflp(p) := if kind = 1 then [p[1], 2*off - p[2]]
            elseif kind = 2 then [2*off - p[1], p[2]]
            elseif kind = 3 then [p[2] - off, p[1] + off]
            else [off - p[2], off - p[1]];

orig : tri;
img : map(reflp, tri);

x1 : orig[1][1]; y1 : orig[1][2];
x2 : orig[2][1]; y2 : orig[2][2];
x3 : orig[3][1]; y3 : orig[3][2];
xx1 : img[1][1]; yy1 : img[1][2];
xx2 : img[2][1]; yy2 : img[2][2];
xx3 : img[3][1]; yy3 : img[3][2];

/* human-readable description of a line given [kind, off] */
desc(k, o) := if k = 1 then (if o = 0 then "Reflection in the x-axis" else sconcat("Reflection in the line y = ", o))
  elseif k = 2 then (if o = 0 then "Reflection in the y-axis" else sconcat("Reflection in the line x = ", o))
  elseif k = 3 then (if o = 0 then "Reflection in the line y = x" else sconcat("Reflection in the line y = x ", if o > 0 then sconcat("+ ", o) else sconcat("- ", -o)))
  else (if o = 0 then "Reflection in the line y = -x" else sconcat("Reflection in the line y = -x ", if o > 0 then sconcat("+ ", o) else sconcat("- ", -o)));

description : desc(kind, off);

/* wrong-line distractor: the "confusable" partner line -- swap the axis
   (y = k  <->  x = k) or flip the diagonal's sign (y = x + c  <->  y = -x + c).
   This is always a different line, so it is a genuine near-miss
   (e.g. correct x = -2  gives the distractor  y = -2). */
swapline(k, o) := if k = 1 then [2, o] elseif k = 2 then [1, o] elseif k = 3 then [4, o] else [3, o];
wsel : swapline(kind, off);
wrongline_desc : desc(wsel[1], wsel[2]);

/* MCQ options: token value, correct?, display text */
ta : random_permutation([
  [opt_correct,   true,  description],
  [opt_wrongline, false, wrongline_desc],
  [opt_rot,       false, "This transformation is a rotation"],
  [opt_trans,     false, "This is a translation (a slide, with no turning or flipping)"],
  [opt_none,      false, "This is not a transformation"]
]);

kindcode : kind;
lineoff : off;
